209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
212	        HttpHeaders headers = new HttpHeaders();
213	        Visit visit = visitMapper.toVisit(visitFieldsDto);
214	        Pet pet = new Pet();
215	        pet.setId(petId);
216	        visit.setPet(pet);
217	        this.clinicService.saveVisit(visit);
218	        VisitDto visitDto = visitMapper.toVisitDto(visit);
219	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
220	            .buildAndExpand(visit.getId()).toUri());
221	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
222	    }
